import{_ as o,l as s,o as e,c as i,v as n,p as l,x as r,d as h,i as d,S as m}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"期权链作为现货信号","description":"","frontmatter":{"title":"期权链作为现货信号","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/options-as-spot-signal.md","filePath":"quant/options-as-spot-signal.md","lastUpdated":1789023840000}'),E={name:"quant/options-as-spot-signal.md"};function p(u,a,A,c,B,f){const t=s("Mermaid");return e(),i("div",null,[a[1]||(a[1]=n('<h1 id="期权链作为现货信号" tabindex="-1">期权链作为现货信号 <a class="header-anchor" href="#期权链作为现货信号" aria-label="Permalink to &quot;期权链作为现货信号&quot;">​</a></h1><div class="epigraph"><p>期权成交量中的非公开信息会进入期权价格，并随后出现在股票上；期权市场可以是股票信息的侧门，而不是仅仅对已有股价做波动定价。</p><footer>—— Easley, O&#39;Hara and Srinivas, Option Volume and Stock Prices: Evidence on Where Informed Traders Trade, Journal of Finance, 1998</footer></div><p><a href="/quant/news-nlp-alpha">上一课</a>把文本因子写成词典 / 主题 / 监督分层，并强调时间戳与 IDF 前视；公司新闻因子换手高，扣费后往往只留下短窗口。缺口是衍生品链上还有一套现货特征：隐含波动形状、看涨看跌量比、平价偏离，是否包含尚未写入股票中间价的信息。Easley–O&#39;Hara–Srinivas 从知情交易选择场所出发；Muravyev 等人给出股票往往领先的反面证据。本课把期权链当横截面信号，不重写 Tetlock 词表。目标是股票预期收益，不是复制方差互换。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>文本因子回答的是词表、时间戳与中性化。留下的是链上每一个点同时含有风险中性预期、溢价、摩擦与可能的知情交易。期权价格由无套利与做市库存共同决定。链上的每一个点同时含有：对未来二次变差与跳跃的风险中性预期、波动风险溢价、买卖价差与离散行权价的插值误差、以及可能的知情交易。当作现货信号时，必须声明抽取的是哪一块。Smirk 更接近下跌保护的价格，可能是崩盘溢价（Bates）而不是「知情者在买看跌」。量比更接近订单流，可能是知情或只是对冲需求（指数期权尤其如此）。平价偏离在存在借券费与提前行权时可以是摩擦，不是预测。问题是把<strong>风险溢价、摩擦与信息</strong>分开，否则横截面排序只是把高 IV、高 skew 的小盘股再卖空一遍。</p><p>测量依赖链的质量。短到期、薄行权价上的隐含波动噪声极大，须用成交或买卖报价、Δ 范围、到期日筛选，与<a href="/quant/vol-surface">波动率曲面</a>同一套清洁规则。用结算价反解 IV 在远翼会得到假 smirk，信号来自插值而不是交易。</p><h3 id="领先滞后与「场所选择」不是自动成立" tabindex="-1">领先滞后与「场所选择」不是自动成立 <a class="header-anchor" href="#领先滞后与「场所选择」不是自动成立" aria-label="Permalink to &quot;领先滞后与「场所选择」不是自动成立&quot;">​</a></h3><p>Easley–O&#39;Hara–Srinivas 的机制是：杠杆与卖空成本使知情者选择期权。经验上这随名字变化：大盘股的股票市场已经深度足够，Muravyev 等对报价的结论更接近「股票主导价格发现」。小盘、难借券的名字上，期权开仓量的增量信息更合理（Pan–Poteshman 使用开仓而非总成交，正是为了去掉平仓噪声）。把 SPX 期权的 PCR 当成 S&amp;P 现货择时，对象是宏观对冲需求，与个股截面不是同一回归。</p><p><span class="marginnote">用当日期权 IV 解释当日股票收益，多半是共同跳跃：股票跌则 skew 变陡。预测必须用 \\(t\\) 日收盘后可获得的链去预测 \\(t+1\\) 起的收益，并处理美股盘后与期权收盘的时钟差。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>形状类。</strong> 固定期限（例如 30 日）插值出虚值看跌与平值的 IV 差（Xing–Zhang–Zhao 的 smirk）、25-delta 风险反转、以及无模型偏度（Bakshi–Kapadia–Madan 式，Conrad、Dittmar、Ghysels 2013 把事前偏度推进收益截面）。这些量要按<a href="/quant/cs-rank-features">截面 rank</a> 并控制 IV 水平，否则只是在交易波动风险溢价的另一张面孔。Goyal 与 Saretto（2009）表明实现–隐含差预测的是<strong>期权</strong>收益；把它原样搬到股票上需要单独检验，不能引用同一张表。</p><p><strong>流量类。</strong> 看跌开仓 / 看涨开仓（Pan–Poteshman）、期权成交相对股票成交（Johnson–So）、主动买入虚值看跌的份额。流量必须用带方向的成交或至少可靠的报价规则，盘口标识错误会把做市对冲当成知情买入。指数与个股应分开：指数期权是宏观对冲池。</p><p><strong>平价与限制。</strong> Cremers–Weinbaum 的隐含波动差（看涨 IV 减看跌 IV）在控制借券与期权买卖价差后是否仍预测股票，是在问信息还是摩擦。Ofek–Richardson–Whitelaw 提醒：卖空限制下股票可以相对期权高估，此时「信号」是可借券量的代理，容量由证券借贷市场决定，不是由期权链深度决定。</p><h3 id="与现货微观结构对照" tabindex="-1">与现货微观结构对照 <a class="header-anchor" href="#与现货微观结构对照" aria-label="Permalink to &quot;与现货微观结构对照&quot;">​</a></h3><p>若信号真是知情流入，它应与股票侧的<a href="/quant/order-imbalance">订单不平衡</a>同向或领先一短窗，而不是完全正交。若完全正交且只在高 IV 名字上显著，更像波动因子。Chakravarty、Gulen 与 Mayhew（2004）讨论期权与股票的价格发现份额，随期权成交活跃度变化。复制应分样本：期权流动性高的名字 vs 低的名字；后者的 IV 形状不可信，前者的信息优势更弱——这是令人不快但诚实的权衡。</p><p><span class="marginnote">Delta 对冲后的期权组合收益（波动溢价）与未对冲的方向性信号常被一张「期权因子」表混在一起。现货信号必须明确：左边是股票收益，还是对冲后的期权收益。Goyal–Saretto 与 Xing–Zhang–Zhao 的左边不同。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>风险通道：虚值看跌贵，对应负跳风险溢价，高 smirk 的股票期望收益可以更低（投资者为下跌保护付费，或这些股票本身更像高杠杆的左尾资产）。这是定价，不是「期权告诉你股票会跌所以做空能稳定赚钱」——做空这些名字可能是在收取崩盘溢价，在压力周一次性还回去，见<a href="/quant/evt">极值</a>与拥挤。</p><p>信息通道：知情者买虚值看跌或买看涨，量与平价偏离暂时离开摩擦边界，随后股票跟上。该通道的容量受期权买卖价差与做市商对冲冲击限制：你在期权里看到的「信息」可能是做市商即将在股票里对冲的方向，领先时间以分钟计，日频截面里会被平均掉。这也是 Muravyev 等在报价层面更悲观的原因。</p><p>摩擦通道：难借券 → 合成空头（买看跌卖看涨）相对便宜，平价偏离，同时股票因卖空限制高估。信号有效，但实施要用期权合成或付出借券费，净边缘回到<a href="/quant/net-edge">可交易性</a>。</p><h3 id="期限结构与持有期" tabindex="-1">期限结构与持有期 <a class="header-anchor" href="#期限结构与持有期" aria-label="Permalink to &quot;期限结构与持有期&quot;">​</a></h3><p>短到期链对隔夜跳与周末更敏感，信号换手高、噪声大。长到期更接近风险溢价与盈利不确定，衰减慢。应画 IC 对到期日、对预测期 \\(h\\) 的热图，避免用 7 日期权预测下月收益这种期限错配。指数与个股的期限结构不同：VIX 期限结构是宏观状态，个股 30 日 smirk 是截面。把 VIX 当个股特征的共同因子即可，不要每个名字再减一遍同一 VIX。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要用未清洁的远翼 IV。不要在涨跌停或期权停牌日假设链可交易。美式提前行权、分红与借券使平价不是欧式公式，须用期货或远期作底层。A 股与内地期权品种少、做市制度不同，美股个股文献不能直接当参数。对冲需求在财报日、指数到期日（witching）会淹没信息，这些日历应单独报告或剔除，见<a href="/quant/calendar-overnight">日历与隔夜</a>。</p><p>希腊字母风险：用期权表达现货观点会引入 Vega 与 Gamma，账本需要<a href="/quant/greeks-hedge">对冲</a>与<a href="/quant/trading-kill-switch">闸门</a>，否则「现货信号」在波动上升日变成波动赌博。</p><p><span class="marginnote">开盘集合竞价与隔夜新闻使股票跳空，期权 IV 在开盘重定价。用前一日收盘链预测当日开盘到收盘，和预测开盘跳空是两个标签；混用会把已实现跳当成预测神力。</span></p>',26)),(e(),l(m,null,{default:r(()=>[d(t,{id:"mermaid-76",class:"mermaid",graph:"flowchart%20TD%0A%20%20CHAIN%5B%22%E6%B8%85%E6%B4%81%E5%90%8E%E7%9A%84%E6%9C%9F%E6%9D%83%E9%93%BE%22%5D%20--%3E%20SHAPE%5B%22smirk%20%2F%20%E6%97%A0%E6%A8%A1%E5%9E%8B%E5%81%8F%E5%BA%A6%20%2F%20IV-RV%22%5D%0A%20%20CHAIN%20--%3E%20FLOW%5B%22%E5%BC%80%E4%BB%93%20PCR%20%2F%20O%2FS%20%E9%87%8F%E6%AF%94%22%5D%0A%20%20CHAIN%20--%3E%20PAR%5B%22%E5%B9%B3%E4%BB%B7%E5%81%8F%E7%A6%BB%E4%B8%8E%E5%80%9F%E5%88%B8%22%5D%0A%20%20SHAPE%20--%3E%20SPLIT%7B%22%E9%A3%8E%E9%99%A9%E6%BA%A2%E4%BB%B7%E8%BF%98%E6%98%AF%E4%BF%A1%E6%81%AF%3F%22%7D%0A%20%20FLOW%20--%3E%20SPLIT%0A%20%20PAR%20--%3E%20SPLIT%0A%20%20SPLIT%20--%3E%20STK%5B%22%E8%82%A1%E7%A5%A8%E9%9A%8F%E5%90%8E%E6%94%B6%E7%9B%8A%22%5D%0A%20%20STK%20--%3E%20CHK%5B%22%E7%9B%B8%E5%AF%B9%E8%82%A1%E7%A5%A8%E8%AE%A2%E5%8D%95%E6%B5%81%E4%B8%8E%E8%B4%B9%E7%94%A8%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=n('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Easley–O&#39;Hara–Srinivas（1998）与 Pan–Poteshman（2006）提供知情交易进入期权流量的理论与开仓量证据；Muravyev–Pearson–Broussard（2013）表明报价层面股票往往仍领先。</li><li>Xing–Zhang–Zhao（2010）的 smirk、Cremers–Weinbaum（2010）的平价偏离、Johnson–So（2012）的量比、Bali–Hovakimian（2009）的 IV–RV，抽取的是链上不同切片，不可合成一个未经中性化的「期权因子」。</li><li>形状类信号高度共线于波动与崩盘溢价；流量类依赖开仓标识与场所流动性；平价类常是卖空摩擦（Ofek–Richardson–Whitelaw）。</li><li>日频现货预测必须用可获得链、正确时钟，并扣期权与股票两侧成本；短领先若只存在于分钟级，不属于日频 alpha。</li><li>出处：Easley, O&#39;Hara and Srinivas, <em>JF</em>, 1998；Pan and Poteshman, <em>JF</em>, 2006；Xing, Zhang and Zhao, <em>JFQA</em>, 2010；Cremers and Weinbaum, <em>JF</em>, 2010；Ofek, Richardson and Whitelaw, <em>RFS</em>, 2004；Johnson and So, <em>JFE</em>, 2012；Bali and Hovakimian, <em>JFQA</em>, 2009；Muravyev, Pearson and Broussard, <em>JFE</em>, 2013；Goyal and Saretto, <em>JFE</em>, 2009；Conrad, Dittmar and Ghysels, <em>JF</em>, 2013；Chakravarty, Gulen and Mayhew, <em>JF</em>, 2004。</li></ul>',2))])}const g=o(E,[["render",p]]);export{S as __pageData,g as default};
